@app.callback(invoke_without_command=True)
def main(
    ctx: typer.Context,
    version: bool = typer.Option(
        False, "--version", callback=_version_callback, help="Show version and exit."
    ),
    backend: str | None = typer.Option(
        None, "--backend", help="Backend to use: local (SQLite) | mcp (remote server)."
    ),
    db: str | None = typer.Option(
        None, "--db", help="Path to the local SQLite database (local backend)."
    ),
    mcp_url: str | None = typer.Option(
        None, "--mcp-url", help="MCP server URL (mcp backend)."
    ),
) -> None:
    """Agentic ODI: manage Customer Outcomes locally or against an MCP server."""
    ctx.obj = BackendConfig(backend=backend, db_path=db, mcp_url=mcp_url)
    if ctx.invoked_subcommand is None:
        typer.echo(ctx.get_help())
        raise typer.Exit()

def _truncate(text: str, width: int = _STATEMENT_WIDTH) -> str:
    return text if len(text) <= width else text[: width - 1] + "…"


def _num(value: Any) -> str:
    """Render numeric scores to two decimals; pass anything else through."""
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, (int, float)):
        return f"{value:.2f}"
    return str(value)

ConfigOption = typer.Option(
    None,
    "--config",
    help="Path to the connectors JSON registry.",
    envvar="AGENTIC_ODI_CONNECTORS_FILE",
)

_CONNECTOR_TIMEOUT = 30.0


def _connector_timeout() -> float:
    raw = os.getenv("AGENTIC_ODI_CONNECTOR_TIMEOUT")
    if not raw:
        return _CONNECTOR_TIMEOUT
    try:
        return float(raw)
    except ValueError:
        return _CONNECTOR_TIMEOUT


def _run(coro, name: str):
    """Run a connector coroutine with a bounded timeout and clean failure."""
    timeout = _connector_timeout()
    try:
        return asyncio.run(asyncio.wait_for(coro, timeout=timeout))
    except asyncio.TimeoutError as exc:
        typer.echo(f"Error: connector '{name}' timed out after {timeout:.0f}s", err=True)
        raise typer.Exit(code=1) from exc

